ST.xhtml:p:
R_TringOpen(CLK := g_bThreeSidesCenterOpenM);
R_TringClose(CLK := g_bThreeSidesCenterCloseM);
R_TringSetValue(CLK := g_bFourSidesCenterSetValueM);
R_TringManula(CLK := bManualHMI);
IF R_TringOpen.Q THEN
  g_bThreeSidesCenterOpenM := FALSE;
  nThreesidesstate := 10;
  g_dUseSideCenterType := 7.0;
  g_bExecuteSingeSideOnAFace := FALSE;
  g_bExecuteSingeSideOnBFace := FALSE;
  g_bExecuteSingeSideOnCFace := FALSE;
  g_bExecuteSingeSideOnDFace := FALSE;
END_IF;
IF R_TringClose.Q THEN
  g_bThreeSidesCenterCloseM := FALSE;
  nThreesidesstate := 20;
END_IF;
IF R_TringManula.Q THEN
  g_dInformHmiUpdateValue := 8.0;
  bManualHMI := FALSE;
END_IF;

CASE nThreesidesstate OF
  0:
  nThreesidesstate := 0;
  10:
  IF R_TringSetValue.Q THEN
    IF g_nFourSidesCenterSetValueP = 0 THEN
      dThreeSidesCompensationA := g_dFourSidesCenterSetValueQ;
    ELSIF g_nFourSidesCenterSetValueP = 1 THEN
      dThreeSidesCompensationB := g_dFourSidesCenterSetValueQ;
    ELSIF g_nFourSidesCenterSetValueP = 2 THEN
      dThreeSidesCompensationD := g_dFourSidesCenterSetValueQ;  
    END_IF;
    g_bFourSidesCenterSetValueM := FALSE;
  END_IF;
    IF g_bPlcPauseBuffer THEN
      nThreesidesstate := 30;
    END_IF;
  20:
    g_dThreeSidesCenterCompensationA := dThreeSidesCompensationA - g_dBeamCenterPos;
    g_dThreeSidesCenterCompensationB := dThreeSidesCompensationB - g_dBeamCenterPos;
    g_dThreeSidesCenterCompensationD := dThreeSidesCompensationD - g_dBeamCenterPos;
    g_dInformHmiUpdateValue := 8.0;
    nThreesidesstate := 0;
    IF ABS(g_dThreeSidesCenterCompensationA)>g_dCompensationThreshold OR ABS(g_dThreeSidesCenterCompensationB) > g_dCompensationThreshold
      OR ABS(g_dThreeSidesCenterCompensationD) > g_dCompensationThreshold THEN
      g_bExcessiveDeviationOfCentringCompensationAlarm := TRUE;
    END_IF;
  30:
    IF g_bPlcStartBuffer THEN
      nThreesidesstate := 10;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer OR g_bPlcEndM THEN
  nThreesidesstate := 0;
END_IF;
